function pvLimpa(h){const d=new DOMParser().parseFromString('<div>'+String(h||'')+'</div>','text/html');const OK=['B','STRONG','I','EM','U','SUB','SUP','BR','P','DIV','UL','OL','LI','H3','SPAN','IMG','TABLE','TBODY','TR','TD','TH','S','AUDIO','A'];
  const vai=n=>{[...n.childNodes].forEach(c=>{if(c.nodeType===3)return;if(c.nodeType!==1||!OK.includes(c.tagName)){if(c.nodeType===1&&!['SCRIPT','STYLE','IFRAME','OBJECT','META','LINK'].includes(c.tagName)){vai(c);c.replaceWith(...c.childNodes)}else c.remove();return}
    [...c.attributes].forEach(a=>{const ok=(c.tagName==='IMG'&&a.name==='src'&&/^data:image\/(png|jpe?g|gif|webp);base64,/i.test(a.value))||(c.tagName==='AUDIO'&&((a.name==='src'&&/^data:audio\/[a-z0-9.+-]+(;codecs=[a-z0-9.,]+)?;base64,/i.test(a.value))||a.name==='controls'))||(c.tagName==='A'&&a.name==='href'&&/^https?:\/\//i.test(a.value))||(c.tagName==='SPAN'&&a.name==='class'&&/^(fr|fn|fd|rd)$/.test(a.value));if(!ok)c.removeAttribute(a.name)});
    if(c.tagName==='A'){c.setAttribute('target','_blank');c.setAttribute('rel','noopener')}if(c.tagName==='AUDIO')c.setAttribute('controls','');if((c.tagName==='IMG'||c.tagName==='AUDIO')&&!c.getAttribute('src'))c.remove();else vai(c)})};
  const r=d.body.firstChild;vai(r);return r.innerHTML.trim()}
const pvHa=ts=>{if(!ts)return '';const m=Math.floor((Date.now()-ts)/60000);if(m<1)return 'agora';if(m<60)return 'há '+m+' min';const h=Math.floor(m/60);if(h<24)return 'há '+h+' h';const d=Math.floor(h/24);if(d<31)return 'há '+d+' dia'+(d===1?'':'s');const me=Math.floor(d/30);if(me<12)return 'há '+me+(me===1?' mês':' meses');const a=Math.floor(d/365);return 'há '+a+' ano'+(a===1?'':'s')};
