function pvImg(file,max){max=max||1000;return new Promise((ok,ko)=>{if(!file||!/^image\//.test(file.type))return ko(new Error('Escolha uma imagem.'));const rd=new FileReader();rd.onerror=()=>ko(new Error('Não foi possível ler a imagem.'));
  rd.onload=()=>{const im=new Image();im.onerror=()=>ko(new Error('Imagem inválida.'));im.onload=()=>{const k=Math.min(1,max/Math.max(im.width,im.height));const cv=document.createElement('canvas');cv.width=Math.round(im.width*k);cv.height=Math.round(im.height*k);const cx=cv.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,cv.width,cv.height);cx.drawImage(im,0,0,cv.width,cv.height);
    const png=file.type==='image/png'&&cv.width*cv.height<250000;ok(cv.toDataURL(png?'image/png':'image/jpeg',.78))};im.src=rd.result};rd.readAsDataURL(file)})}
