/* gravar áudio (enunciados de línguas, ditados…): até 60 s, guardado na prova */
async function pvGravarAudio(cb){let st;try{st=await navigator.mediaDevices.getUserMedia({audio:true})}catch(_){return toast('Não foi possível usar o microfone.','erro')}
  const tipo=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>window.MediaRecorder&&MediaRecorder.isTypeSupported(t))||'';const rec=new MediaRecorder(st,tipo?{mimeType:tipo,audioBitsPerSecond:32000}:{});const P=[];let t0=Date.now(),tm;
  rec.ondataavailable=e=>P.push(e.data);rec.onstop=()=>{clearInterval(tm);st.getTracks().forEach(x=>x.stop());const b=new Blob(P,{type:rec.mimeType||'audio/webm'});const r=new FileReader();r.onload=()=>{closeDrawer();cb(String(r.result).replace(/^data:audio\/([a-z0-9]+)[^;]*;/i,'data:audio/$1;'))};r.readAsDataURL(b)};
  openDrawer('Gravar áudio',`<div class="ed" style="text-align:center"><p class="pvrec0">● <b id="ga-t">0:00</b> / 1:00</p><p class="hint">A gravar… fale para o microfone.</p><button class="btn pri" id="ga-ok">${ic('check',14)} Parar e inserir</button> <button class="btn ghost" id="ga-x">Cancelar</button></div>`);
  rec.start();tm=setInterval(()=>{const s=Math.floor((Date.now()-t0)/1000);const e=$('#ga-t');if(e)e.textContent='0:'+String(s).padStart(2,'0');if(s>=60)rec.stop()},250);
  $('#ga-ok').onclick=()=>rec.stop();$('#ga-x').onclick=()=>{rec.onstop=()=>{clearInterval(tm);st.getTracks().forEach(x=>x.stop())};rec.stop();closeDrawer()}}
