function pvAvMais(a){openDrawer(a.titulo,`<div class="ed"><div class="armais">
  <button class="btn" data-pm="ex">${ic('pencil',15)} Editar</button><button class="btn" data-pm="ag">${ic('calendar',15)} Agendar</button><button class="btn" data-pm="ativ">${ic('eye',15)} Acompanhar</button><button class="btn" data-pm="resp">${ic('checks',15)} Correção (${a.resp.length})</button><button class="btn" data-pm="est">${ic('chart',15)} Estatísticas</button>
  <button class="btn" data-pm="tu">${ic('users',15)} Turmas e Momentos de Avaliação</button><button class="btn" data-pm="dup">${ic('copy',15)} Duplicar</button><button class="btn" data-pm="sh">${ic('send',15)} Partilhar com colegas</button><button class="btn" data-pm="pdf">${ic('printer',15)} Versão em papel (imprimir / PDF)</button><button class="btn" data-pm="rel">${ic('printer',15)} Relatórios individuais (PDF)</button><button class="btn" data-pm="csv">${ic('download',15)} Exportar respostas (Excel)</button><button class="btn dng" data-pm="x">${ic('trash',15)} Apagar</button></div></div>`);
  $$('#dw-b [data-pm]').forEach(b=>b.onclick=()=>{const k=b.dataset.pm;
    if(['ex','ativ','resp','est'].includes(k)){closeDrawer();UI.pvEd={k:'av',id:a.id};UI.pvAt=k;return vProvas()}
    if(k==='ag')return pvAgendarDlg(a);if(k==='tu')return pvAssocDlg(a);if(k==='sh')return pvPartilharDlg('av',a);if(k==='csv')return pvCSV(a);if(k==='rel'){closeDrawer();return pvRelatorios(a)}if(k==='pdf'){closeDrawer();return pvPapel(a)}
    if(k==='dup'){const c=pvClone(a);Object.assign(c,{id:uid(),titulo:a.titulo+' (cópia)',resp:[],sess:[],assoc:[],ag:{},criado:Date.now(),alterado:Date.now(),publicado:false});c.itens.forEach(q=>q.id=uid());PV().av.unshift(c);save();closeDrawer();toast('Duplicada','ok');return vProvas()}
    if(k==='x'){if(!confirm('Apagar «'+a.titulo+'» e as '+a.resp.length+' respostas?'))return;(a.sess||[]).forEach(s=>pvFechar(a,s).catch(()=>{}));S.pv.av=PV().av.filter(x=>x!==a);save();closeDrawer();UI.pvEd=null;vProvas()}})}
/* versão em papel (Intuitivo: exportar para PDF) */
function pvPapel(a){const w=window.open('','_blank');if(!w)return toast('O navegador bloqueou a janela.','erro');let n=0;
  const corpo=a.itens.map(q=>{if(q.tipo==='secao')return `<h2>${esc(q.titulo||'')}</h2>`;if(q.tipo==='info')return `<div class="info">${pvLimpa(q.html)}</div>`;n++;let r='';
    if(q.tipo==='escolha')r='<ol type="A">'+q.ops.map(o=>`<li>${esc(o.t)}</li>`).join('')+'</ol>';
    else if(q.tipo==='vf')r='<table>'+q.linhas.map(l=>`<tr><td>${esc(l.t)}</td><td class="b">V</td><td class="b">F</td></tr>`).join('')+'</table>';
    else if(q.tipo==='texto')r=q.longo?'<div class="lin"></div><div class="lin"></div><div class="lin"></div><div class="lin"></div>':'<div class="lin"></div>';
    else if(q.tipo==='lacunas'){const P=pvLacPartes(q);r='<p>'+P.map((x,k)=>esc(x)+(k<P.length-1?' ________ ':'')).join('')+'</p>'+(q.modo!=='escrever'?'<p class="mut">Palavras: '+esc(pvBaralhar([...pvLacunas(q).map(x=>x[0]),...(q.extraP||[])]).join(' · '))+'</p>':'')}
    else if(q.tipo==='ordem')r='<p>'+pvBaralhar(q.ops).map(o=>'☐ '+esc(o.t)).join('<br>')+'</p>';
    else if(q.tipo==='ligar'){const D=pvBaralhar(q.pares.map(p=>p.b));r='<table>'+q.pares.map((p,k)=>`<tr><td>${k+1}. ${esc(p.a)}</td><td style="width:40px"></td><td>${String.fromCharCode(65+k)}. ${esc(D[k])}</td></tr>`).join('')+'</table>'}
    else if(q.tipo==='tabela')r=`<table><tr><th></th>${q.cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr>${q.lins.map(l=>`<tr><th>${esc(l)}</th>${q.cols.map(()=>'<td class="b">☐</td>').join('')}</tr>`).join('')}</table>`;
    else if(q.tipo==='legendar'||q.tipo==='segmentos')r=`<div class="leg"><img src="${q.img}">${q.tipo==='legendar'?q.marcas.map((m,k)=>`<i style="left:${m.x}%;top:${m.y}%">${k+1}</i>`).join(''):''}</div>${q.tipo==='legendar'?q.marcas.map((m,k)=>`<p>${k+1}. ____________________</p>`).join(''):''}`;
    return `<div class="q"><p class="n"><b>${n}.</b> <span class="p">(${nf(q.pts)} pts)</span></p>${pvLimpa(q.html)}${r}${q.just?'<p class="mut">Justificação:</p><div class="lin"></div><div class="lin"></div>':''}</div>`}).join('');
  w.document.write(`<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><title>${esc(a.titulo)}</title><style>body{font:13px/1.45 system-ui,sans-serif;color:#111;margin:16mm}h1{font-size:19px;margin:0 0 4px}.cab{border-bottom:1.5px solid #111;padding-bottom:8px;margin-bottom:14px}.q{break-inside:avoid;margin:0 0 16px}.n{margin:0 0 4px}.p{color:#555;font-size:12px}img{max-width:100%;max-height:300px}table{border-collapse:collapse;margin:6px 0}td,th{border:1px solid #999;padding:4px 8px}td.b{width:30px;text-align:center}.lin{border-bottom:1px solid #999;height:24px}.mut{color:#555}.leg{position:relative;display:inline-block}.leg i{position:absolute;transform:translate(-50%,-50%);background:#111;color:#fff;border-radius:50%;width:20px;height:20px;font:700 11px/20px sans-serif;text-align:center;font-style:normal}.info{border:1px solid #ccc;border-radius:6px;padding:8px;margin-bottom:14px}</style></head><body><div class="cab"><h1>${esc(a.titulo)}</h1><p>Nome: ______________________________ N.º ____ Turma ____ Data ___/___/____ · Cotação total: ${nf(pvPts(a))} pts</p>${a.desc?`<p>${esc(a.desc)}</p>`:''}</div>${corpo}<script>setTimeout(()=>print(),400)<\/script></body></html>`);w.document.close()}

