  const nv=$('#pe-nav');if(nv)nv.onclick=()=>{const a=pvAvNova('');a.itens=S_().map(pvParaItem);save();UI.pvSelEx=[];UI.pvEd={k:'av',id:a.id};UI.pvAt='ex';vProvas()};
