function pvValidar(w){if(!pvTxt(w.html)&&!/<img/.test(w.html||''))return 'Escreva o enunciado.';
  if(w.tipo==='escolha'){if(w.ops.filter(o=>o.t.trim()).length<2)return 'Ponha pelo menos duas opções.';if(!w.ops.some(o=>o.certa&&o.t.trim()))return 'Escolha a opção correta (botão ✓ à esquerda).'}
  if(w.tipo==='lacunas'&&!pvLacunas(w).length)return 'Escolha pelo menos uma palavra a esconder.';
  if(w.tipo==='ordem'&&w.ops.filter(o=>o.t.trim()).length<2)return 'Ponha pelo menos dois itens.';
  if(w.tipo==='ligar'&&w.pares.filter(p=>p.a.trim()&&p.b.trim()).length<2)return 'Ponha pelo menos dois pares completos.';
  if(w.tipo==='tabela'&&(w.cols.some(c=>!c.trim())||w.lins.some(c=>!c.trim())))return 'Escreva todos os cabeçalhos da tabela.';
  if(w.tipo==='legendar'&&(!w.img||!w.marcas.length||w.marcas.some(m=>!String(m.t||'').trim())))return 'Carregue a imagem, marque as legendas e escreva a resposta de cada uma.';
  if(w.tipo==='segmentos'&&(!w.img||!w.zonas.length))return 'Carregue a imagem e desenhe pelo menos uma zona.';return ''}
