function pvResumo(q){const ok=b=>b?'<b class="pvok2">✓</b>':'';
  if(q.tipo==='escolha')return `<ul class="pvres">${q.ops.map(o=>`<li class="${o.certa?'c':''}">${esc(o.t)} ${ok(o.certa)}</li>`).join('')}</ul>`;
  if(q.tipo==='vf')return `<ul class="pvres">${q.linhas.map(l=>`<li>${esc(l.t||'Resposta')}: <b>${l.v?'Verdadeiro':'Falso'}</b></li>`).join('')}</ul>`;
  if(q.tipo==='texto')return `<p class="mut peq">${q.longo?'Resposta longa'+(q.rub?' · rubrica: '+esc((PV().rub.find(r=>r.id===q.rub)||{}).nome||'?'):''):'Resposta curta · aceites: '+esc((q.resp||[]).join(' / ')||'—')}</p>`;
  if(q.tipo==='lacunas'){const P=pvLacPartes(q),G=pvLacunas(q);return `<p>${P.map((x,k)=>esc(x)+(k<P.length-1?`<span class="pvgap">${esc(G[k].join(' / '))}</span>`:'')).join('')}</p><p class="mut peq">${q.modo==='arrastar'?'Banco de palavras':q.modo==='escolher'?'Escolher':'Escrever'}${(q.extraP||[]).length?' · extra: '+esc(q.extraP.join(', ')):''}</p>`}
  if(q.tipo==='ordem')return `<ol class="pvres">${q.ops.map(o=>`<li>${esc(o.t)}</li>`).join('')}</ol>`;
  if(q.tipo==='ligar')return `<ul class="pvres">${q.pares.map(p=>`<li>${esc(p.a)} → <b>${esc(p.b)}</b></li>`).join('')}</ul>`;
  if(q.tipo==='tabela')return pvTabHtml(q,q.marc);
  if(q.tipo==='legendar')return `<div class="pvleg sm">${q.img?`<img src="${q.img}" alt="">`:''}${q.marcas.map((m,k)=>`<i style="left:${m.x}%;top:${m.y}%">${k+1}</i>`).join('')}</div><p class="mut peq">${q.marcas.map((m,k)=>(k+1)+'. '+esc(m.t)).join(' · ')}</p>`;
  if(q.tipo==='segmentos')return `<div class="pvleg sm">${pvSegHtml(q,[]).replace(/^<div class="pvleg">|<\/div>$/g,'')}</div>`;return ''}
