function pvEstat(a,el){const R_=a.resp;const Q=pvPerg(a).filter(q=>+q.pts);if(!R_.length){el.innerHTML=`<div class="pvempty">${ic('chart',36)}<p><b>Ainda não há submissões</b></p></div>`;return}
  const TT=A()?A().turmas:[];const F=UI.pvEf=UI.pvEf||{tid:''};const RR=F.tid?R_.filter(r=>r.tid===F.tid):R_;const P=RR.map(r=>({r,p:pvPontuar(a,r)}));const mx=pvPts(a)||1;
  const pc=P.map(x=>x.p.tot/mx*100).sort((x,y)=>x-y);const med=pc.reduce((s,x)=>s+x,0)/(pc.length||1);const mdn=pc.length?(pc.length%2?pc[(pc.length-1)/2]:(pc[pc.length/2-1]+pc[pc.length/2])/2):0;const dp=Math.sqrt(pc.reduce((s,x)=>s+(x-med)**2,0)/(pc.length||1));
  const apr=pc.filter(x=>x>=50).length;const tm=P.map(x=>(x.r.t1||0)-(x.r.t0||x.r.t1||0)).filter(x=>x>0);const tmed=tm.length?tm.reduce((s,x)=>s+x,0)/tm.length:0;const pend=P.reduce((s,x)=>s+x.p.pend,0);
  const hist=Array(10).fill(0);pc.forEach(x=>hist[Math.min(9,Math.floor(x/10))]++);const hm=Math.max(1,...hist);
  const ord=P.slice().sort((x,y)=>y.p.tot-x.p.tot);const k27=Math.max(1,Math.round(P.length*.27));const sup=ord.slice(0,k27),inf=ord.slice(-k27);
  const st=q=>{const v=P.map(x=>x.p.pq[q.id]).filter(x=>x!=null);const m=v.length?v.reduce((s,x)=>s+x,0)/v.length/(+q.pts):null;const ms=sup.map(x=>x.p.pq[q.id]).filter(x=>x!=null),mi=inf.map(x=>x.p.pq[q.id]).filter(x=>x!=null);
    const di=ms.length&&mi.length?(ms.reduce((s,x)=>s+x,0)/ms.length-mi.reduce((s,x)=>s+x,0)/mi.length)/(+q.pts):null;return {m,di,n:v.length}};
  const cor=x=>x==null?'var(--mut)':x>=.75?'var(--ok)':x>=.5?'#65a30d':x>=.3?'#d97706':'var(--bad)';
  el.innerHTML=`<div class="pvbar">${TT.filter(t=>R_.some(r=>r.tid===t.id)).length>1?`<select id="pe-tu"><option value="">Todas as turmas</option>${TT.filter(t=>R_.some(r=>r.tid===t.id)).map(t=>`<option value="${t.id}" ${F.tid===t.id?'selected':''}>${esc(t.nome)}</option>`).join('')}</select>`:''}<span class="pvsp"></span><button class="btn sm" id="pe-csv">${ic('download',13)} Exportar (Excel)</button></div>
   <div class="pvstat3 six"><div><b>${P.length}</b><small>Submissões</small></div><div><b>${nf(Math.round(med*10)/10)}%</b><small>Média (${nf(Math.round(med/5)/1)} valores)</small></div><div><b>${nf(Math.round(mdn*10)/10)}%</b><small>Mediana</small></div><div><b>${nf(Math.round(dp*10)/10)}</b><small>Desvio padrão</small></div><div><b>${P.length?Math.round(apr/P.length*100):0}%</b><small>Positivas (≥ 50%)</small></div><div><b>${pvDur(tmed)}</b><small>Tempo médio</small></div></div>
   ${pend?`<p class="pvav">${ic('alert',15)} ${pend} resposta(s) por corrigir à mão — as estatísticas ficam completas depois de as corrigir em Correção.</p>`:''}
   <section class="pvcard"><h3>Distribuição das classificações</h3><div class="pvhist">${hist.map((h,i)=>`<div><i style="height:${h/hm*100}%;background:${cor((i+.5)/10)}" title="${h} aluno(s)"></i><b>${h||''}</b><small>${i*10}–${i===9?100:i*10+9}%</small></div>`).join('')}</div></section>
   <section class="pvcard"><h3>Por exercício</h3><p class="pvhint">Dificuldade = taxa de acerto (média dos pontos ÷ cotação). Discriminação = diferença de acerto entre os 27% melhores e os 27% piores (acima de 0,3 o item distingue bem; perto de 0 ou negativo convém rever).</p>
    <div class="pvtq">${Q.map((q,k)=>{const s=st(q);const al=['vf','lacunas','ligar'].includes(q.tipo)?pvAlineas(Object.assign({},a,{resp:RR}),q):[];return `<div class="pvtqr"><span class="pvtqn">${k+1}</span><div class="pvt"><b>${esc((q.titulo||'').slice(0,90))}</b><div class="pvtqb"><i style="width:${s.m==null?0:s.m*100}%;background:${cor(s.m)}"></i></div>${al.map(x=>`<div class="pvtqa"><span>${esc(x.t)}</span><span>${x.n?Math.round(x.ok/x.n*100):0}%</span></div>`).join('')}</div><span class="pvtqv"><b>${s.m==null?'—':Math.round(s.m*100)+'%'}</b><small>${s.di==null?'':'disc. '+nf(Math.round(s.di*100)/100)}</small></span></div>`}).join('')}</div></section>
   <section class="pvcard"><h3>Por aluno</h3><table class="pvtbl"><tr><th>N.º</th><th>Nome</th><th>Pontos</th><th>%</th><th>0–20</th><th>Tempo</th><th>Saídas</th></tr>${ord.map(x=>`<tr><td>${esc(x.r.num||'')}</td><td>${esc(x.r.nome)}</td><td>${nf(x.p.tot)} / ${nf(x.p.max)}</td><td>${Math.round(x.p.tot/mx*100)}%</td><td><b>${nf(Math.round(x.p.tot/mx*200)/10)}</b></td><td>${pvDur((x.r.t1||0)-(x.r.t0||x.r.t1||0))}</td><td>${(x.r.sai||0)+(x.r.ecra||0)||''}</td></tr>`).join('')}</table></section>`;
  const tu=$('#pe-tu');if(tu)tu.onchange=e=>{F.tid=e.target.value;pvEstat(a,el)};$('#pe-csv').onclick=()=>pvCSV(a)}
